-- =============================================================================
-- V1: Create Users Table
-- =============================================================================
-- Mosaic uses UUID primary keys generated by the database.
-- Timestamps are stored in UTC with timezone (TIMESTAMPTZ).
-- Soft delete is supported via deleted_at.
-- =============================================================================

CREATE TABLE IF NOT EXISTS users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    email_verified BOOLEAN NOT NULL DEFAULT FALSE,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at TIMESTAMPTZ,

    CONSTRAINT uq_users_email UNIQUE (email)
);

-- Index for fast user lookup by email during authentication
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);

-- Index for filtering out soft-deleted users
CREATE INDEX IF NOT EXISTS idx_users_active_not_deleted ON users(is_active) WHERE deleted_at IS NULL;
